    public void configure_regions(Resource source)
    {
        var regions=Array(source,"regions");var previous=new Dictionary<string,Settings>(StringComparer.Ordinal);foreach(var value in regions){var region=value.AsGodotDictionary();previous[region["id"].AsString()]=region;}var dimensions=source.Get("dimensions").AsVector2();float size=source.Get("region_size").AsSingle();regions=regions.Duplicate();regions.Clear();source.Set("regions",regions);var count=(dimensions/size).Ceil();string world=source.Get("world_id").AsString();long seed=source.Get("seed").AsInt64();
        for(int z=0;z<(int)count.Y;z++)for(int x=0;x<(int)count.X;x++){string id=world+":region:"+x+":"+z;var start=new Vector2(x,z)*size-dimensions*.5f;var region=previous.TryGetValue(id,out var old)?old.Duplicate(true):new Settings {["id"]=id,["name"]="Region "+(x+1)+" · "+(z+1),["enabled"]=true,["locked"]=false,["seed"]=unchecked((uint)GD.Hash(new GArray {seed,id}))};region["cell"]=new Vector2I(x,z);region["bounds"]=new Rect2(start,Vector2.One*size).Intersection(new Rect2(-dimensions*.5f,dimensions));regions.Add(region);}
    }
