        var section=GD.Load<GDScript>("res://Workspaces/EnvironmentWorkspace/world/road_section.gd");var roadTypes=section.GetScriptConstantMap()["TYPES"].AsGodotArray().Select(value=>value.AsString()).ToHashSet(StringComparer.Ordinal);
        foreach(var value in roads)
