        foreach(var value in settlements){var settlement=value.AsGodotDictionary();errors.AddRange(districts.Call("validate",settlement).AsStringArray());if(settlement.ContainsKey("road_type")&&!roadTypes.Contains(settlement["road_type"].AsString()))errors.Add("Choose a supported settlement road type.");string id=Get(settlement,"id","").AsString();var center=Get(settlement,"center",Vector3.Zero).AsVector3();double radius=Get(settlement,"radius",48.0).AsDouble();if(id.Length==0||seen.Contains(id)||!center.IsFinite()||Outside(radius,8,512))errors.Add("Settlements need unique IDs, finite centers and a radius from 8 to 512 meters.");seen.Add(id);if(!new[]{"Town","Village","City"}.Contains(Get(settlement,"profile","Town").AsString()))errors.Add("Choose a supported town, village or city profile.");if(!new[]{"Grid","Road network"}.Contains(Get(settlement,"layout_mode","Grid").AsString()))errors.Add("Choose a grid layout or blocks from the road network.");}
        if(forests.Count>16)errors.Add("A world supports up to sixteen editable forest sources.");seen.Clear();var forestProfiles=GD.Load<GDScript>("res://Workspaces/EnvironmentWorkspace/world/world_forests.gd").GetScriptConstantMap()["PROFILES"].AsGodotArray().Select(value=>value.AsString()).ToHashSet(StringComparer.Ordinal);
        foreach(var value in forests){var forest=value.AsGodotDictionary();string id=Get(forest,"id","").AsString();if(id.Length==0||seen.Contains(id)||!Bounds(Get(forest,"bounds",new Rect2()).AsRect2()))errors.Add("Forests need unique IDs and positive finite bounds.");seen.Add(id);if(Outside(Get(forest,"density",1.0).AsDouble(),0,4))errors.Add("Forest density must be between zero and four.");if(!forestProfiles.Contains(Get(forest,"profile","").AsString()))errors.Add("Choose a supported forest profile.");}
