    public long geometry_signature(Resource source)=>Signature(source,new[]{"world_id","seed","dimensions","region_size","terrain_id","owned_terrain_id","regions","nodes","roads","settlements","connect_settlements","connection_bridges","connection_road_type","connection_overrides","forests","prop_rules","exclusions","occupied","respect_existing_objects","plot_overrides","max_building_plots","eager_building_limit","terrain_dependency_key"});
